def _iouDeviceEditSlot(self):
    """
    Edits an IOU device.
    """

    item = self.uiIOUDevicesTreeWidget.currentItem()
    if item:
        key = item.data(0, QtCore.Qt.UserRole)
        iou_device = self._iou_devices[key]
        dialog = ConfigurationDialog(iou_device["name"], iou_device, iouDeviceConfigurationPage(), parent=self)
        dialog.show()
        if dialog.exec_():
            new_name = item.text(0)
            if iou_device["name"] != new_name:
                if "{}:{}'.format(iou_device["server"], new_name) in self._iou_devices:
                    QtGui.QMessageBox.critical(self, "New IOU device", "IOU device name {} already exists".format(new_name))
                else:
                    iou_device["name"] = new_name
                    item.setText(0, new_name)
            self._refreshInfo(iou_device)
